import React, { useMemo, useCallback, useEffect } from 'react';
import TextArea from './TextArea';
import VisualizedData from './VisualizedData/VisualizedData';
import { Footer } from './Footer';
import { Header } from './Header';
import { useSelector, useDispatch } from 'react-redux';
import { RootState } from '.';
import { textareaSlice } from './features/textarea/textareaSlice';
import { dataSlice } from './features/data/dataSlice';

const minFrameWidth = 1;

export const Page: React.FC = () => {
  const isDragging = useSelector(
    (state: RootState) => state.textarea.isDragging
  );
  const width = useSelector((state: RootState) => state.textarea.width);

  const { setWidth, setDragging } = textareaSlice.actions;
  const dispatch = useDispatch();
  const { setData } = dataSlice.actions;
  window.onmessage = function(e) {
    console.log('onmessage Page.tsx '+e.data.initial_set_json)
    console.log(e)
    if (e.data.initial_set_json) {
      console.log('Received initial_set_json')
        delete e.data.initial_set_json
        let site_config = e.data.site_config_json
        site_config._sn_site_id = e.data._sn_site_id
        dispatch(setData(site_config));
    }
  };

  const onMouseDown = useCallback(() => {
    dispatch(setDragging(true));
  }, [setDragging, dispatch]);
  const onMouseUpOrLeave = useCallback(() => {
    dispatch(setDragging(false));
  }, [setDragging, dispatch]);
  const onMouseMove = useCallback(
    (event: React.MouseEvent) => {
      if (isDragging) {
        const newWidth = event.clientX;
        if (newWidth > minFrameWidth) {
          dispatch(setWidth(newWidth));
        }
      }
    },
    [isDragging, setWidth, dispatch]
  );

  const leadingStyle = useMemo(() => {
    return {
      width: width,
    };
  }, [width]);

  useEffect(() => {
    if (window.innerWidth < 576) {
      dispatch(setWidth(window.innerWidth));
    }
  }, [dispatch, setWidth]);

  return (
    <>
      <Header />
      <main
        className="d-flex flex-sm-row flex-column flex-grow-1 h-100"
        onMouseMove={onMouseMove}
        onMouseUp={onMouseUpOrLeave}
        onMouseLeave={onMouseUpOrLeave}
      >
        <div
          // className="leading-side d-flex flex-column p-2"
          className="leading-side d-none flex-column p-2"
          
          style={leadingStyle}
          
        >
          <TextArea />
        </div>
        <div
          // className="adjuster d-flex justify-content-center align-items-center"
          className="adjuster d-none justify-content-center align-items-center"
          onMouseDown={onMouseDown}
        >
          <i className="fas fa-ellipsis-v" />
        </div>
        <div className="trailing-side d-flex flex-column flex-grow-1 pr-2 pl-1">
          <div className="flex-grow-1">
            <div className="scroll-wrapper">
              <VisualizedData />
            </div>
          </div>
        </div>
      </main>
      <Footer />
    </>
  );
};
